import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.BbQrW5_t.js";const u=JSON.parse('{"title":"初中数学奥数教程","description":"","frontmatter":{"title":"初中数学奥数教程","date":"2026-09-05T00:00:00.000Z","tags":["初中数学","奥数"]},"headers":[],"relativePath":"study/junior-math/olympiad/index.md","filePath":"study/junior-math/olympiad/index.md","lastUpdated":null}'),l={name:"study/junior-math/olympiad/index.md"};function i(n,t,o,s,h,p){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="初中数学奥数教程" tabindex="-1">初中数学奥数教程 <a class="header-anchor" href="#初中数学奥数教程" aria-label="Permalink to &quot;初中数学奥数教程&quot;">​</a></h1><blockquote><p>覆盖<strong>数论、代数、几何、组合</strong>四大模块 24 章，每章含知识点精讲、经典例题（详细解答）、配套习题（附答案提示）。难度定位：华罗庚金杯、希望杯、初中数学联赛初赛及 CSP-J 数学基础水平。</p></blockquote><h2 id="四大模块" tabindex="-1">四大模块 <a class="header-anchor" href="#四大模块" aria-label="Permalink to &quot;四大模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>章节数</th><th>核心内容</th><th>竞赛权重</th></tr></thead><tbody><tr><td><a href="./number-theory/">数论</a></td><td>6</td><td>整除、质因数分解、约数倍数、奇偶分析、同余、不定方程</td><td>★★★★★</td></tr><tr><td><a href="./algebra/">代数</a></td><td>6</td><td>绝对值、因式分解、分式根式、韦达定理、不等式最值、函数综合</td><td>★★★★★</td></tr><tr><td><a href="./geometry/">几何</a></td><td>6</td><td>全等辅助线、等腰对称、面积等积变形、相似、圆幂定理、几何变换</td><td>★★★★☆</td></tr><tr><td><a href="./combinatorics/">组合</a></td><td>6</td><td>排列组合、抽屉原理、容斥、染色覆盖、博弈策略、逻辑推理</td><td>★★★★☆</td></tr></tbody></table><h2 id="建议学习路线" tabindex="-1">建议学习路线 <a class="header-anchor" href="#建议学习路线" aria-label="Permalink to &quot;建议学习路线&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一学期（初一）：数论 1-4 章 → 组合 1-2 章 → 代数 1-2 章</span></span>
<span class="line"><span>第二学期（初二）：代数 3-4 章 → 几何 1-4 章 → 组合 3-4 章</span></span>
<span class="line"><span>第三学期（初三）：数论 5-6 章 → 代数 5-6 章 → 几何 5-6 章 → 组合 5-6 章</span></span></code></pre></div><p>原则：<strong>数论和组合先行</strong>（不依赖年级进度），几何紧随校内全等/相似进度，函数综合放最后。</p><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h2><ol><li>先读「知识点精讲」，动手推导每个公式</li><li>例题<strong>先自己想 15 分钟</strong>再看解答，重点研究「方法提炼」</li><li>习题独立完成，对照折叠区的答案提示复盘</li><li>每章末的「方法小结」建议整理进自己的错题/方法本</li></ol><h2 id="配套资源" tabindex="-1">配套资源 <a class="header-anchor" href="#配套资源" aria-label="Permalink to &quot;配套资源&quot;">​</a></h2><ul><li><a href="./../visual-tools.html">图形化理解工具</a>——用编程可视化数学本质</li><li><a href="./../exam/">中考真题案例</a>——奥数方法在中考压轴题的应用</li></ul>`,11)])])}const m=a(l,[["render",i]]);export{u as __pageData,m as default};
